def _ledger(revision_priority, tax_base, refund):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            revision = event.get("revision", 0)
            if revision_priority == "sequence_first":
                key = (sequence, revision, position)
            else:
                key = (revision, position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if refund and event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        domains = {}
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            domains[name] = versions

        best_vector = None
        best = None
        assignments = {}

        def valid():
            installed = {name for name, version in assignments.items() if version is not None}
            if any(name not in installed or not low <= assignments[name] <= high
                   for name, (low, high) in roots.items()):
                return False

            edges = {name: [] for name in installed}
            closure = set(roots)
            stack = list(roots)
            while stack:
                name = stack.pop()
                version = assignments.get(name)
                if version is None:
                    return False
                row = next((r for r in packages[name] if r["version"] == version), None)
                if row is None:
                    return False
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = assignments.get(other)
                    if other_version is None or not dep["min"] <= other_version <= dep["max"]:
                        return False
                    edges[name].append(other)
                    if other not in closure:
                        closure.add(other)
                        stack.append(other)
            if closure != installed:
                return False

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True
            return all(visit(name) for name in installed)

        def search(index):
            nonlocal best_vector, best
            if index == len(names):
                if valid():
                    vector = tuple(assignments[name] if assignments[name] is not None else -1
                                   for name in names)
                    if best_vector is None or vector > best_vector:
                        best_vector = vector
                        best = {name: assignments[name] for name in names
                                if assignments[name] is not None}
                return
            name = names[index]
            # Trying larger versions first is not required for correctness, but may find
            # the lexicographic optimum early.
            for version in sorted(domains[name], reverse=True):
                assignments[name] = version
                search(index + 1)
            assignments[name] = None
            search(index + 1)
            del assignments[name]

        search(0)
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


def _component_07():
    from itertools import combinations

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        options = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            # With half-open intervals, jobs ending at a time do not overlap
            # jobs beginning at that same time.
            points = sorted({job["start"] for job in subset} |
                            {job["end"] for job in subset})
            if any(sum(job["start"] <= point < job["end"] for job in subset) > 2
                   for point in points):
                continue
            value = sum(job["value"] for job in subset)
            chosen_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and chosen_ids > best_ids)):
                best_value, best_ids = value, chosen_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _component_08():
    import heapq

    def solve(data):
        n = data["n"]
        graph = [[] for _ in range(n)]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source, target = data["source"], data["target"]
        initial_mask = bit.get(source, 0)
        coupons = data["coupons"]
        start = data["start"]
        initial = (source, initial_mask, coupons)
        distances = {initial: start}
        queue = [(start, source, initial_mask, coupons)]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == target and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                duration = edge["duration"]
                options = [(duration, remaining)]
                if remaining:
                    options.append((max(1, duration - edge.get("discount", 0)), remaining - 1))
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                for travel, left in options:
                    arrival = depart + travel
                    if arrival > data["deadline"]:
                        continue
                    nxt = (next_node, next_mask, left)
                    if arrival < distances.get(nxt, float("inf")):
                        distances[nxt] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, left))
        return {"arrival": None}
    return solve


